#!/bin/bash
# 디스커션 본문(표준입력)의 멤버별·기타 칸("### 📝 …", "### 📑 …") 제목 위에 구분선(---)을 넣어 출력한다 (#133)
# - 회의록(📝 이름, 📑 기타)과 멘토링(📝 내용) 둘 다 같은 규칙. 칸끼리 줄로 나뉘어 읽기 쉬워진다
# - 바로 위에 이미 구분선이 있으면 다시 넣지 않는다. 코드 블록(``` … ```) 안은 건드리지 않는다
set -euo pipefail

cat | tr -d '\r' | awk '
  /^```/ { in_code = !in_code }
  !in_code && /^### (📝|📑) / && last != "---" { print "---"; print "" }
  { print; if ($0 !~ /^[[:space:]]*$/) { last = $0; sub(/^[[:space:]]+/, "", last); sub(/[[:space:]]+$/, "", last) } }
'
